## Installation

```bash
npx shadcn@latest add @akoder/copy-command-block
```

## Usage

```tsx
import { CopyCommandBlock } from "@/components/ui/copy-command-block";

export function Command() {
  return <CopyCommandBlock commands={{ npm: "npm i motion", pnpm: "pnpm add motion" }} />;
}
```
